const upsertIntegrationJob = `-- name: UpsertIntegrationJob :one
INSERT INTO integration_jobs (
    organization_id, integration_account_id, direction, provider, kind, idempotency_key, payload, ref_type, ref_uuid
) VALUES (
    $1, $2, $3, $4,
    $5, $6, $7, $8, $9
)
ON CONFLICT (provider, idempotency_key) DO UPDATE
SET deliveries = integration_jobs.deliveries + 1
RETURNING id, uuid, organization_id, status, attempts, deliveries, (xmax = 0)::boolean AS inserted
`

type UpsertIntegrationJobParams struct {
	OrganizationID       pgtype.Int8 `json:"organization_id"`
	IntegrationAccountID pgtype.Int8 `json:"integration_account_id"`
	Direction            string      `json:"direction"`
	Provider             string      `json:"provider"`
	Kind                 string      `json:"kind"`
	IdempotencyKey       string      `json:"idempotency_key"`
	Payload              []byte      `json:"payload"`
	RefType              string      `json:"ref_type"`
	RefUuid              pgtype.UUID `json:"ref_uuid"`
}

type UpsertIntegrationJobRow struct {
	ID             int64       `json:"id"`
	Uuid           uuid.UUID   `json:"uuid"`
	OrganizationID pgtype.Int8 `json:"organization_id"`
	Status         string      `json:"status"`
	Attempts       int32       `json:"attempts"`
	Deliveries     int32       `json:"deliveries"`
	Inserted       bool        `json:"inserted"`
}

// Records a job once per provider and idempotency key; a repeated key
// counts the delivery and returns the existing row (inserted = false).
func (q *Queries) UpsertIntegrationJob(ctx context.Context, arg UpsertIntegrationJobParams) (UpsertIntegrationJobRow, error) {
	row := q.db.QueryRow(ctx, upsertIntegrationJob,
		arg.OrganizationID,
		arg.IntegrationAccountID,
		arg.Direction,
		arg.Provider,
		arg.Kind,
		arg.IdempotencyKey,
		arg.Payload,
		arg.RefType,
		arg.RefUuid,
	)
	var i UpsertIntegrationJobRow
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.OrganizationID,
		&i.Status,
		&i.Attempts,
		&i.Deliveries,
		&i.Inserted,
	)
	return i, err
}
